//! Turns one input line into a validated [`Command`].
//!
//! This covers the first three steps of the error order in SPEC.md section 2
//! (request shape, required parameters, parameter values). Everything that
//! needs queue state happens later, in the broker.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode, Result};

/// Attributes named in a request; `None` means "not given".
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct AttributePatch {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Send {
    pub queue: String,
    pub body: String,
    pub delay_seconds: Option<u32>,
    pub group_id: Option<String>,
    pub deduplication_id: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Command {
    CreateQueue { queue: String, attributes: AttributePatch },
    SetQueueAttributes { queue: String, attributes: AttributePatch },
    GetQueueAttributes { queue: String },
    ListQueues { prefix: Option<String> },
    DeleteQueue { queue: String },
    PurgeQueue { queue: String },
    Tick { seconds: u32 },
    SendMessage(Send),
    ReceiveMessage { queue: String, max_messages: usize, visibility_timeout: Option<u32> },
    DeleteMessage { queue: String, receipt_handle: String },
    ChangeMessageVisibility { queue: String, receipt_handle: String, visibility_timeout: u32 },
}

fn invalid_value(what: &str) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, format!("invalid value for {what}"))
}

/// The members of a JSON object, with `null` read as absent.
struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|n| self.get(n).is_none()) {
            Some(name) => Err(Error::new(
                ErrorCode::MissingParameter,
                format!("missing parameter {name}"),
            )),
            None => Ok(()),
        }
    }

    fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| v.as_str().ok_or_else(|| invalid_value(name)))
            .transpose()
    }

    fn required_string(&self, name: &str) -> Result<&'a str> {
        self.require(&[name])?;
        self.string(name)?.ok_or_else(|| invalid_value(name))
    }

    fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        self.get(name)
            .map(|v| {
                v.as_u64()
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| range.contains(n))
                    .ok_or_else(|| invalid_value(name))
            })
            .transpose()
    }

    fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| invalid_value(name)))
            .transpose()
    }

    /// A 1 to 128 character string of `A-Z a-z 0-9 _ -`.
    fn identifier(&self, name: &str) -> Result<Option<String>> {
        match self.string(name)? {
            Some(s) if (1..=128).contains(&s.len()) && s.chars().all(is_name_char) => {
                Ok(Some(s.to_owned()))
            }
            Some(_) => Err(invalid_value(name)),
            None => Ok(None),
        }
    }
}

fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

fn is_valid_queue_name(name: &str) -> bool {
    match name.strip_suffix(".fifo") {
        Some(stem) => (1..=75).contains(&stem.len()) && stem.chars().all(is_name_char),
        None => (1..=80).contains(&name.len()) && name.chars().all(is_name_char),
    }
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

fn parse_attributes(value: &Value) -> Result<AttributePatch> {
    let Value::Object(map) = value else {
        return Err(invalid_value("Attributes"));
    };
    if let Some(unknown) = map
        .iter()
        .find(|(k, v)| !v.is_null() && !ATTRIBUTE_NAMES.contains(&k.as_str()))
    {
        return Err(Error::new(
            ErrorCode::InvalidParameterValue,
            format!("unknown attribute {}", unknown.0),
        ));
    }
    let p = Params(map);
    Ok(AttributePatch {
        visibility_timeout: p.integer("VisibilityTimeout", 0..=43_200)?,
        delay_seconds: p.integer("DelaySeconds", 0..=900)?,
        retention_seconds: p.integer("RetentionSeconds", 60..=1_209_600)?,
        fifo: p.boolean("Fifo")?,
        content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
        dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
        max_receive_count: p.integer("MaxReceiveCount", 1..=1000)?,
    })
}

fn optional_attributes(p: &Params) -> Result<AttributePatch> {
    p.get("Attributes").map_or_else(|| Ok(AttributePatch::default()), parse_attributes)
}

/// Parses one input line (without its line terminator).
pub fn parse(line: &[u8]) -> Result<Command> {
    let not_request = |why: &str| Error::new(ErrorCode::InvalidRequest, why.to_owned());
    let text = std::str::from_utf8(line).map_err(|_| not_request("line is not valid UTF-8"))?;
    let value: Value = serde_json::from_str(text).map_err(|e| not_request(&e.to_string()))?;
    let Value::Object(map) = value else {
        return Err(not_request("line is not a JSON object"));
    };
    let Some(Value::String(command)) = map.get("Command") else {
        return Err(not_request("Command is missing or not a string"));
    };
    let p = Params(&map);
    let queue = || p.required_string("QueueName").map(str::to_owned);

    Ok(match command.as_str() {
        "CreateQueue" => {
            p.require(&["QueueName"])?;
            let queue = queue()?;
            if !is_valid_queue_name(&queue) {
                return Err(Error::new(ErrorCode::QueueNameInvalid, "invalid queue name"));
            }
            Command::CreateQueue { queue, attributes: optional_attributes(&p)? }
        }
        "SetQueueAttributes" => {
            p.require(&["QueueName", "Attributes"])?;
            let queue = queue()?;
            let attributes = optional_attributes(&p)?;
            Command::SetQueueAttributes { queue, attributes }
        }
        "GetQueueAttributes" => Command::GetQueueAttributes { queue: queue()? },
        "ListQueues" => Command::ListQueues { prefix: p.string("Prefix")?.map(str::to_owned) },
        "DeleteQueue" => Command::DeleteQueue { queue: queue()? },
        "PurgeQueue" => Command::PurgeQueue { queue: queue()? },
        "Tick" => {
            p.require(&["Seconds"])?;
            let seconds = p.integer("Seconds", 0..=1_209_600)?;
            Command::Tick { seconds: seconds.ok_or_else(|| invalid_value("Seconds"))? }
        }
        "SendMessage" => {
            p.require(&["QueueName", "Body"])?;
            let queue = queue()?;
            let body = p.required_string("Body")?;
            if !(1..=1024).contains(&body.len()) {
                return Err(invalid_value("Body"));
            }
            Command::SendMessage(Send {
                queue,
                body: body.to_owned(),
                delay_seconds: p.integer("DelaySeconds", 0..=900)?,
                group_id: p.identifier("GroupId")?,
                deduplication_id: p.identifier("DeduplicationId")?,
            })
        }
        "ReceiveMessage" => {
            p.require(&["QueueName"])?;
            let queue = queue()?;
            let max = p.integer("MaxMessages", 1..=10)?.unwrap_or(1);
            Command::ReceiveMessage {
                queue,
                max_messages: usize::try_from(max).map_err(|_| invalid_value("MaxMessages"))?,
                visibility_timeout: p.integer("VisibilityTimeout", 0..=43_200)?,
            }
        }
        "DeleteMessage" => {
            p.require(&["QueueName", "ReceiptHandle"])?;
            Command::DeleteMessage {
                queue: queue()?,
                receipt_handle: p.required_string("ReceiptHandle")?.to_owned(),
            }
        }
        "ChangeMessageVisibility" => {
            p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
            let queue = queue()?;
            let receipt_handle = p.required_string("ReceiptHandle")?.to_owned();
            let seconds = p.integer("VisibilityTimeout", 0..=43_200)?;
            Command::ChangeMessageVisibility {
                queue,
                receipt_handle,
                visibility_timeout: seconds.ok_or_else(|| invalid_value("VisibilityTimeout"))?,
            }
        }
        other => return Err(not_request(&format!("unknown command {other}"))),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn code(line: &str) -> ErrorCode {
        parse(line.as_bytes()).unwrap_err().code
    }

    #[test]
    fn shape_errors_are_invalid_request() {
        for line in ["", "[]", "{", r#"{"Command": 1}"#, r#"{"Command": "Nope"}"#, r#"{"Command": null}"#] {
            assert_eq!(code(line), ErrorCode::InvalidRequest, "{line}");
        }
        assert_eq!(parse(b"{\"Command\":\"Tick\",\"Seconds\":1}\xff").unwrap_err().code, ErrorCode::InvalidRequest);
    }

    #[test]
    fn missing_beats_invalid_value() {
        let line = r#"{"Command":"SendMessage","Body":5}"#;
        assert_eq!(code(line), ErrorCode::MissingParameter);
    }

    #[test]
    fn null_counts_as_absent() {
        let line = r#"{"Command":"Tick","Seconds":null}"#;
        assert_eq!(code(line), ErrorCode::MissingParameter);
    }

    #[test]
    fn integers_must_be_plain_in_range() {
        for seconds in ["30.0", "3e1", "\"30\"", "-1", "1209601", "true"] {
            let line = format!(r#"{{"Command":"Tick","Seconds":{seconds}}}"#);
            assert_eq!(code(&line), ErrorCode::InvalidParameterValue, "{seconds}");
        }
        let ok = parse(br#"{"Command":"Tick","Seconds":1209600}"#).unwrap();
        assert_eq!(ok, Command::Tick { seconds: 1_209_600 });
    }

    #[test]
    fn queue_names() {
        for (name, valid) in [
            ("a", true),
            ("a.fifo", true),
            (".fifo", false),
            ("a.b", false),
            ("a b", false),
            ("é", false),
            ("", false),
            (&"a".repeat(80), true),
            (&"a".repeat(81), false),
            (&format!("{}.fifo", "a".repeat(75)), true),
            (&format!("{}.fifo", "a".repeat(76)), false),
        ] {
            assert_eq!(is_valid_queue_name(name), valid, "{name}");
        }
    }

    #[test]
    fn create_queue_checks_name_before_attributes() {
        let line = r#"{"Command":"CreateQueue","QueueName":"a b","Attributes":5}"#;
        assert_eq!(code(line), ErrorCode::QueueNameInvalid);
        let line = r#"{"Command":"CreateQueue","QueueName":"ab","Attributes":{"Bogus":1}}"#;
        assert_eq!(code(line), ErrorCode::InvalidParameterValue);
    }

    #[test]
    fn body_is_limited_in_bytes() {
        let ok = format!(r#"{{"Command":"SendMessage","QueueName":"q","Body":"{}"}}"#, "é".repeat(512));
        assert!(parse(ok.as_bytes()).is_ok());
        let long = ok.replace("é\"", "éé\"");
        assert_eq!(code(&long), ErrorCode::InvalidParameterValue);
        let empty = r#"{"Command":"SendMessage","QueueName":"q","Body":""}"#;
        assert_eq!(code(empty), ErrorCode::InvalidParameterValue);
    }
}
