//! All queues plus the virtual clock and the id counters; executes commands.

use std::collections::BTreeMap;

use serde_json::{Map, Value, json};

use crate::error::{Error, ErrorCode, Result};
use crate::queue::{Accepted, Attributes, DeadLetter, Message, Queue};
use crate::request::{self, AttributePatch, Command, Send};

type Members = Map<String, Value>;

const MAX_QUEUES: usize = 1000;
const MAX_MESSAGES: usize = 100_000;

fn reply<const N: usize>(members: [(&str, Value); N]) -> Members {
    members.into_iter().map(|(k, v)| (k.to_owned(), v)).collect()
}

fn fail<T>(code: ErrorCode, message: &str) -> Result<T> {
    Err(Error::new(code, message))
}

/// Looks a queue up and applies retention, so callers see current contents.
fn find<'a>(queues: &'a mut BTreeMap<String, Queue>, name: &str, now: u64) -> Result<&'a mut Queue> {
    let queue = queues
        .get_mut(name)
        .ok_or_else(|| Error::new(ErrorCode::QueueDoesNotExist, format!("no queue named {name:?}")))?;
    queue.sweep(now);
    Ok(queue)
}

/// `r-<n>` written exactly as issued, without sign, padding or spaces.
fn parse_handle(text: &str) -> Option<u64> {
    let digits = text.strip_prefix("r-")?;
    if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    digits.parse().ok()
}

#[derive(Debug)]
pub struct Broker {
    queues: BTreeMap<String, Queue>,
    now: u64,
    next_message_id: u64,
    next_receipt: u64,
}

impl Default for Broker {
    fn default() -> Self {
        Self { queues: BTreeMap::new(), now: 0, next_message_id: 1, next_receipt: 1 }
    }
}

impl Broker {
    /// Runs one input line and returns the one-line response (no newline).
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let result = request::parse(line).and_then(|command| self.execute(command));
        let response = match result {
            Ok(mut members) => {
                members.insert("ok".to_owned(), Value::Bool(true));
                Value::Object(members)
            }
            Err(e) => json!({
                "ok": false,
                "error": {"code": e.code.as_str(), "message": e.message},
            }),
        };
        response.to_string()
    }

    pub fn execute(&mut self, command: Command) -> Result<Members> {
        match command {
