use std::io::Write;
use std::process::{Command, Stdio};

fn run(input: &[u8]) -> Vec<String> {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(input).unwrap();
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success());
    String::from_utf8(out.stdout).unwrap().lines().map(str::to_owned).collect()
}

#[test]
fn send_receive_delete_roundtrip() {
    let out = run(br#"{"Command":"CreateQueue","QueueName":"q"}

{"Command":"SendMessage","QueueName":"q","Body":"hi"}
{"Command":"ReceiveMessage","QueueName":"q"}
{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-1"}
{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-1"}"#);
    assert_eq!(out.len(), 6);
    assert_eq!(out[0], r#"{"ok":true}"#);
    assert!(out[1].contains(r#""code":"InvalidRequest""#));
    assert_eq!(out[2], r#"{"MessageId":"m-1","ok":true}"#);
    assert!(out[3].contains(r#""ReceiptHandle":"r-1""#) && out[3].contains(r#""Body":"hi""#));
    assert_eq!(out[4], r#"{"ok":true}"#);
    assert!(out[5].contains(r#""code":"ReceiptHandleExpired""#));
}

